import blue from './images/bean_blue-T1LZ5JXS.png';
import green from './images/bean_green-CgLXJr3U.png';
import orange from './images/bean_orange-CBaY_1LU.png';
import pinkDark from './images/bean_pink_dark-s6lKiPFd.png';
import pinkLight from './images/bean_pink_light-DuuIg89H.png';
import purple from './images/bean_purple-B_GnRU9Z.png';
import red from './images/bean_red-DpephyQd.png';
import teal from './images/bean_teal-gKAVfKmK.png';
import yellow from './images/bean_yellow.png';

// Approximate base color of each official Jelly Belly bean render.
const BEANS: { rgb: [number, number, number]; src: string }[] = [
  { rgb: [42, 79, 201], src: blue },
  { rgb: [46, 139, 46], src: green },
  { rgb: [240, 122, 62], src: orange },
  { rgb: [232, 96, 110], src: pinkDark },
  { rgb: [226, 150, 150], src: pinkLight },
  { rgb: [122, 63, 192], src: purple },
  { rgb: [200, 16, 46], src: red },
  { rgb: [60, 193, 214], src: teal },
  { rgb: [245, 180, 0], src: yellow },
];

const cache = new Map<string, string>();

/** Picks the branded bean image closest to a hex color (memoized). */
function beanFor(hex: string): string {
  const hit = cache.get(hex);
  if (hit) return hit;
  const n = parseInt(hex.replace('#', ''), 16);
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  let best = BEANS[0];
  let bestDist = Infinity;
  for (const bean of BEANS) {
    const d = (bean.rgb[0] - r) ** 2 + (bean.rgb[1] - g) ** 2 + (bean.rgb[2] - b) ** 2;
    if (d < bestDist) {
      bestDist = d;
      best = bean;
    }
  }
  cache.set(hex, best.src);
  return best.src;
}

interface Props {
  color: string;
  size?: number;
  rotate?: number;
  className?: string;
}

/** Jelly Belly branded bean. Decorative, so empty alt text. */
export default function JellyBean({ color, size = 64, rotate = 0, className }: Props) {
  return (
    <img
      className={`jb ${className ?? ''}`}
      src={beanFor(color)}
      alt=""
      width={size}
      draggable={false}
      loading="lazy"
      style={rotate ? { transform: `rotate(${rotate}deg)` } : undefined}
    />
  );
}
